import {useEffect,useMemo,useState} from 'react';
import {AlertTriangle,GitCompareArrows,RefreshCw,Trash2,X} from 'lucide-react';
import {compareExternalHealthRecords,getExternalHealthTrends,listExternalHealthRecords,removeExternalHealthRecord} from '../../lib/externalTransientReportApi';
import {formatDateOnlyDDMMYYYY} from '../../lib/externalClientProfile.mjs';

const dateLabel=value=>value?formatDateOnlyDDMMYYYY(value):'Date unavailable';
const REASONS=['WRONG_CLIENT','WRONG_REPORT','DUPLICATE','BAD_EXTRACTION','QA_TEST_DATA','OTHER'];

export default function ExternalHealthRecords({clientId,onChanged,dateMetadata={},onSaveDates}){
  const [records,setRecords]=useState([]);const [trends,setTrends]=useState([]);const [comparison,setComparison]=useState([]);const [previous,setPrevious]=useState('');const [latest,setLatest]=useState('');const [remove,setRemove]=useState(null);const [busy,setBusy]=useState(false);const [loadState,setLoadState]=useState('loading');const [error,setError]=useState('');
  const active=useMemo(()=>records.filter(item=>item.status==='ACTIVE'),[records]);
  const load=async()=>{setBusy(true);setLoadState('loading');setError('');try{const [recordResult,trendResult]=await Promise.all([listExternalHealthRecords(clientId),getExternalHealthTrends(clientId)]);setRecords(recordResult.records||[]);setTrends(trendResult.trends||[]);setLoadState('ready');}catch(reason){setError(reason.message||'Health records could not be loaded.');setLoadState('failed');}finally{setBusy(false)}};
  useEffect(()=>{void load()},[clientId]);
  const compare=async()=>{setBusy(true);setError('');try{const result=await compareExternalHealthRecords(clientId,previous,latest);setComparison(result.comparison||[]);}catch(reason){setError(reason.message||'These records could not be compared.');}finally{setBusy(false)}};
  const confirmRemove=async event=>{event.preventDefault();setBusy(true);setError('');try{await removeExternalHealthRecord(clientId,remove.record.id,remove.reason,remove.detail);setRemove(null);setComparison([]);await load();await onChanged?.();}catch(reason){setError(reason.message||'Health record could not be removed.');setBusy(false)}};
  return <div className="space-y-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><h3 className="text-xl font-semibold">Health Records</h3><p className="mt-1 text-sm text-slate-500">Dated evidence events. Source report files are not retained.</p></div><button onClick={load} disabled={busy} className="min-h-11 rounded-xl border px-4 text-sm font-semibold"><RefreshCw className="mr-2 inline" size={16}/>Refresh</button></header>{loadState==='failed'&&<section role="alert" className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"><p className="font-semibold">Health Records could not be loaded.</p><p className="mt-1">{error} No empty state has been inferred.</p><button onClick={load} className="mt-3 min-h-11 rounded-lg border border-red-300 bg-white px-4 font-semibold">Retry</button></section>}
    {loadState==='loading'&&!records.length?<p role="status" className="rounded-2xl bg-white p-8 text-center text-sm text-slate-500">Loading health records…</p>:loadState==='ready'&&records.length===0?<div className="rounded-2xl border border-dashed p-10 text-center text-sm text-slate-500"><strong className="block text-slate-700">Confirmed empty</strong><span className="mt-1 block">No confirmed Health Records yet. Lab evidence remains optional.</span></div>:loadState==='ready'?<div className="grid gap-3 md:grid-cols-2">{records.map(record=>{const dates=dateMetadata[record.id]||{};const reportDate=dates.report_date||record.reportDate;const confirmedAt=dates.confirmation_date||record.confirmedAt;return <article key={record.id} className={`rounded-2xl border bg-white p-5 ${record.status==='ACTIVE'?'border-slate-200':'border-amber-200 opacity-75'}`}><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wide text-blue-700">{String(record.recordType||'LAB_REPORT').replaceAll('_',' ')}</p><h4 className="mt-1 font-semibold">{dateLabel(record.sampleDate||reportDate||record.analysisDate)}</h4></div><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold">{record.processingStatus||record.status}</span></div><dl className="mt-4 grid gap-2 text-sm sm:grid-cols-2"><div><dt className="text-xs text-slate-500">Provider / lab</dt><dd className="font-medium">{record.providerName||'Not recorded'}</dd></div><div><dt className="text-xs text-slate-500">Observations</dt><dd className="font-medium">{record.biomarkerCount??0} confirmed</dd></div><div><dt className="text-xs text-slate-500">Uploaded by</dt><dd className="font-medium">{String(record.uploadedByType||record.actorType||'Not recorded').replaceAll('_',' ')}</dd></div><div><dt className="text-xs text-slate-500">Review</dt><dd className="font-medium">{String(record.reviewStatus||'CONFIRMED').replaceAll('_',' ')}</dd></div><div><dt className="text-xs text-slate-500">Report date</dt><dd className="font-medium">{dateLabel(reportDate)}</dd></div><div><dt className="text-xs text-slate-500">Confirmed</dt><dd className="font-medium">{dateLabel(confirmedAt)}</dd></div></dl>{onSaveDates&&<form onSubmit={event=>{event.preventDefault();void onSaveDates(record.id,{report_date:event.currentTarget.report_date.value||null,confirmation_date:event.currentTarget.confirmation_date.value||null})}} className="mt-4 grid gap-2 sm:grid-cols-2"><label className="text-xs font-semibold">Report date<input name="report_date" type="date" defaultValue={String(reportDate||'').slice(0,10)} className="mt-1 min-h-11 w-full rounded-lg border px-2"/></label><label className="text-xs font-semibold">Confirmation date<input name="confirmation_date" type="date" defaultValue={String(confirmedAt||'').slice(0,10)} className="mt-1 min-h-11 w-full rounded-lg border px-2"/></label><button className="min-h-11 rounded-lg border px-3 text-xs font-semibold sm:col-span-2">Save record dates</button></form>}<p className="mt-3 text-xs text-slate-500">{String(record.provenance||'SOURCE_NOT_RECORDED').replaceAll('_',' ')} · source file not retained</p>{record.status==='ACTIVE'&&<div className="mt-4 flex flex-wrap gap-2"><button onClick={()=>{setPrevious(record.id);setLatest('')}} className="min-h-11 rounded-lg border px-3 text-xs font-semibold"><GitCompareArrows className="mr-1 inline" size={15}/>Compare</button><button onClick={()=>setRemove({record,reason:'WRONG_REPORT',detail:''})} className="min-h-11 rounded-lg border border-red-200 px-3 text-xs font-semibold text-red-700"><Trash2 className="mr-1 inline" size={15}/>Remove</button></div>}</article>})}</div>:null}
    {active.length>=2&&<section className="rounded-2xl border bg-white p-5"><h4 className="font-semibold">Compare any two records</h4><div className="mt-4 grid gap-3 sm:grid-cols-2"><select aria-label="Previous health record" value={previous} onChange={event=>setPrevious(event.target.value)} className="min-h-11 rounded-xl border px-3"><option value="">Previous / baseline</option>{active.map(item=><option key={item.id} value={item.id}>{dateLabel(item.sampleDate||item.reportDate||item.analysisDate)}</option>)}</select><select aria-label="Latest health record" value={latest} onChange={event=>setLatest(event.target.value)} className="min-h-11 rounded-xl border px-3"><option value="">Latest</option>{active.filter(item=>item.id!==previous).map(item=><option key={item.id} value={item.id}>{dateLabel(item.sampleDate||item.reportDate||item.analysisDate)}</option>)}</select></div><button disabled={!previous||!latest||busy} onClick={compare} className="mt-3 min-h-11 rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white disabled:opacity-40">Compare records</button>{comparison.length>0&&<div className="mt-5 overflow-x-auto"><table className="min-w-[760px] w-full text-left text-sm"><thead><tr className="border-b">{['Biomarker','Previous','Latest','Change','Trend','Reference ranges'].map(label=><th key={label} className="p-2">{label}</th>)}</tr></thead><tbody>{comparison.map(item=><tr key={item.canonicalBiomarkerId} className="border-b"><td className="p-2 font-semibold">{item.biomarker}</td><td className="p-2">{item.previousValue} {item.previousUnit}</td><td className="p-2">{item.latestValue} {item.latestUnit}</td><td className="p-2">{item.comparable?`${item.absoluteChange>0?'+':''}${item.absoluteChange}${item.percentageChange==null?'':` (${item.percentageChange.toFixed(1)}%)`}`:'—'}</td><td className="p-2">{item.trendDirection.replaceAll('_',' ')}{item.message&&<span className="block text-xs text-amber-700">{item.message}</span>}</td><td className="p-2 text-xs">{item.previousReferenceRange||'—'} → {item.latestReferenceRange||'—'}</td></tr>)}</tbody></table></div>}</section>}
    {trends.length>0&&<section className="rounded-2xl border bg-white p-5"><h4 className="font-semibold">Full trends</h4><div className="mt-4 space-y-3">{trends.map(trend=><article key={trend.canonicalBiomarkerId} className="rounded-xl bg-slate-50 p-4"><p className="font-semibold">{trend.biomarker}</p><p className="mt-2 break-words text-sm">{trend.observations.map(item=>`${item.value} ${item.unit} (${dateLabel(item.date)})`).join(' → ')}</p></article>)}</div></section>}
    {remove&&<div className="fixed inset-0 z-50 flex items-end bg-slate-950/50 sm:items-center sm:justify-center sm:p-4"><form onSubmit={confirmRemove} role="dialog" aria-modal="true" aria-labelledby="remove-health-record-title" className="w-full rounded-t-3xl bg-white p-5 sm:max-w-lg sm:rounded-2xl sm:p-6"><div className="flex justify-between gap-3"><div><h3 id="remove-health-record-title" className="text-lg font-semibold">Remove Health Record</h3><p className="mt-1 text-sm text-slate-600">Linked observations will be quarantined, never hard-deleted or moved to another client.</p></div><button type="button" onClick={()=>setRemove(null)} aria-label="Close" className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div><p className="mt-4 flex gap-2 rounded-xl bg-amber-50 p-3 text-sm text-amber-900"><AlertTriangle className="shrink-0" size={18}/>Only evidence conclusively linked to this record will leave active projections.</p><label className="mt-4 block text-sm font-semibold">Reason<select value={remove.reason} onChange={event=>setRemove({...remove,reason:event.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3">{REASONS.map(reason=><option key={reason}>{reason}</option>)}</select></label><label className="mt-4 block text-sm font-semibold">Explanation<textarea required value={remove.detail} onChange={event=>setRemove({...remove,detail:event.target.value})} className="mt-2 w-full rounded-xl border p-3"/></label><button disabled={busy||!remove.detail.trim()} className="mt-5 min-h-11 w-full rounded-xl bg-red-700 font-semibold text-white disabled:opacity-40">{busy?'Quarantining…':'Confirm removal and quarantine'}</button></form></div>}
  </div>;
}
